const I=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const B=(act,id,label,cls='btn')=>`<button type="button" class="${cls}" data-do="${esc(act)}" data-id="${esc(id)}">${label}</button>`;
const E=(icon,text,action='',label='')=>`<div class="empty">${I(icon)}${esc(text)}${action?'<br>'+B('nav',action,esc(label)):''}</div>`;
const badge=(type,color='')=>`<span class="badge-icon ${color}">${I(type)}</span>`;
const money=c=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:0}).format((Number(c)||0)/100);
const date=v=>v?new Date(v).toLocaleDateString('tr-TR',{day:'numeric',month:'short',year:'numeric'}):'—';
const datetime=v=>v?new Date(v).toLocaleString('tr-TR',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}):'—';
let S=null,view=localStorage.getItem('apaka-view')||'admin',route='home',detail='',calendarOffset=0,studentFilter='all',studentSearch='',catalogFilter='all',courseFilter='all',lessonTab='notes',messageRecipient='',monthFilter=new Date().toISOString().slice(0,7),selected=new Set();
const K=k=>(S?.entities||[]).filter(x=>x.kind===k), get=id=>S.entities.find(e=>e.id===id), U=id=>S.users.find(e=>e.id===id)||{name:id===S.user.id?S.user.name:'Kullanıcı',email:''};
const staffView=()=>S.staff&&view==='admin';
const own=t=>(S[t]||[]).filter(x=>x.user_id===S.user.id);
const enrolls=()=>own('enrollments');
const lessons=cid=>K('lesson').filter(e=>e.course_id===cid).sort((a,b)=>(a.data.order||0)-(b.data.order||0));
const completed=id=>own('progress').some(x=>x.lesson_id===id);
const percent=(cid,userId=S.user.id)=>{const ls=lessons(cid);return ls.length?Math.round(ls.filter(l=>S.progress.some(p=>p.lesson_id===l.id&&p.user_id===userId)).length/ls.length*100):0;};
const enrolled=cid=>enrolls().some(e=>e.course_id===cid);
const locked=id=>{const l=get(id);if(!l)return true;if(!enrolled(l.course_id))return true;const ls=lessons(l.course_id),idx=ls.findIndex(x=>x.id===id);return ls.slice(0,idx).some(x=>!completed(x.id));};
const userProgress=id=>{const es=S.enrollments.filter(e=>e.user_id===id);return es.length?Math.round(es.reduce((a,e)=>a+percent(e.course_id,id),0)/es.length):0};
const pill=(text,cls='')=>`<span class="pill ${cls}">${esc(text)}</span>`;
const progress=(v,withLabel=true)=>`<div class="progress-label"><div class="progress"><span style="width:${Math.max(0,Math.min(100,v))}%"></span></div>${withLabel?'<b>'+v+'%</b>':''}</div>`;
function toast(text,error=false){const t=$('#toast');t.textContent=text;t.style.background=error?'#9e4e46':'#225c46';t.classList.add('show');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.remove('show'),5000);}
async function api(path,body){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const j=await r.json();if(!r.ok){if(r.status===401){location.href='/login.html';throw Error('Giriş gerekli.')}throw Error(j.error||'İşlem tamamlanamadı.')}return j;}
async function refresh(){S=await api('state');if(!S.staff)view='student';render();}
function nav(path){$('#modal').close();location.hash=path;if(location.hash.slice(1)===path)readRoute();}
function readRoute(){const h=location.hash.slice(1)||'home';const parts=h.split('/');route=parts[0];detail=parts[1]||'';lessonTab=parts[2]||'notes';render();if(route==='lesson'&&!staffView()&&!locked(detail)){S.lastLesson=detail;api('lesson/'+detail+'/view',{}).catch(()=>{});}}
function modal(title,html){$('#modal').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2>${B('close','', '×','close')}</div>${html}`;$('#modal').showModal();}
function pageHead(title,sub='',action=''){return `<div class="pagehead"><div><h1>${esc(title)}</h1>${sub?'<p>'+esc(sub)+'</p>':''}</div>${action}</div>`;}
function stat(icon,value,label,color=''){return `<div class="card stat">${badge(icon,color)}<div><b>${esc(value)}</b><small>${esc(label)}</small></div></div>`;}
function render(){if(!S)return;const isAdmin=staffView();const studentNav=[['home','home','Ana Sayfa'],['lessons','book','Derslerim'],['homework','pen','Ödevlerim'],['quizzes','quiz','Quizler'],['speaking','chat','Speaking Club'],['resources','file','Kaynaklar'],['calendar','calendar','Takvim'],['certificates','trophy','Sertifikalarım'],['messages','mail','Mesajlar'],['payments','pay','Ödemelerim'],['profile','user','Profil Ayarları']];const adminNav=[['home','home','Ana Sayfa'],['students','users','Öğrenciler'],['courses','book','Eğitimler'],['content','file','Dersler & İçerikler'],['homework','pen','Ödevler'],['quizzes','quiz','Quizler'],['payments','pay','Ödemeler'],['calendar','calendar','Canlı Dersler'],['messages','mail','Mesajlar'],['reports','chart','Raporlar'],['settings','gear','Ayarlar']];const navs=isAdmin?adminNav:studentNav;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="/"><img src="/assets/logo.png" alt="Apaka English Academia"></a><nav aria-label="Panel menüsü">${navs.map(([n,i,l])=>B('nav',n,I(i)+'<span>'+esc(l)+'</span>','navlink '+(route===n||route==='lesson'&&n==='lessons'||route==='quiz'&&n==='quizzes'?'active':''))).join('')}</nav><div class="side-bottom">${!isAdmin?'<img class="encourage" src="/assets/keep-going.jpg" alt="Let’s keep going!">':''}<a class="navlink" href="${esc(S.signout)}" target="_top">${I('logout')}<span>Çıkış Yap</span></a></div></aside><div class="workspace"><header class="topbar">${B('mobile-menu','',I('menu'),'iconbtn mobile-menu')}<div class="searchwrap">${I('search')}<input class="search" id="search" aria-label="Panelde ara" placeholder="${isAdmin?'Öğrenci ara, eğitim veya içerik ara…':'Ders, konu veya kaynak ara…'}"></div><div class="top-right"><button type="button" class="theme-button" data-theme-toggle aria-label="Gece moduna geç">☾</button>${S.staff?B('switch-view','',isAdmin?'Öğrenci Görünümü':'Yönetim Paneli','mode'):''}${B('notifications','',I('bell')+(S.messages.some(m=>m.recipient===S.user.id&&!m.read_at)?'<span class="dot"></span>':''),'iconbtn')}<div class="person"><span class="avatar">${esc(S.user.name.charAt(0).toUpperCase())}</span><div class="person-name"><b>${esc(S.user.name.split(' ')[0])}</b><small>${isAdmin?(S.admin?'Yönetici':'Öğretmen'):esc(S.user.level)+' English'}</small></div></div></div></header><main id="content">${content()}</main></div></div>`;
 document.title='Apaka | '+(isAdmin?'Yönetim Paneli':'Öğrenci Portalı');if(route==='messages'&&S.messages.some(m=>m.recipient===S.user.id&&!m.read_at))api('message-read',{sender:messageRecipient}).then(()=>{S.messages.filter(m=>m.recipient===S.user.id&&m.sender===messageRecipient).forEach(m=>m.read_at=new Date().toISOString())}).catch(()=>{});
 const chat=$('.chat');if(chat)chat.scrollTop=chat.scrollHeight;
}
function content(){if(staffView()){switch(route){case'home':return adminHome();case'students':return students();case'courses':return courses(true);case'content':return adminContent();case'homework':return homework(true);case'quizzes':return quizzes(true);case'payments':return payments(true);case'calendar':case'speaking':return calendar(true);case'messages':return messages();case'reports':return reports();case'settings':return settings();case'lesson':return lesson();case'quiz':return quiz();case'profile':return profile();case'search':return searchResults(detail);case'placement':return placement();default:return adminHome();}}
 switch(route){case'home':return studentHome();case'courses':return courses(false);case'lessons':return myLessons();case'lesson':return lesson();case'quizzes':return quizzes(false);case'quiz':return quiz();case'homework':return homework(false);case'resources':return resources();case'speaking':return speaking();case'calendar':return calendar(false);case'certificates':return certificates();case'certificate':return certificate();case'messages':return messages();case'payments':return payments(false);case'profile':return profile();case'placement':return placement();case'search':return searchResults(detail);default:return studentHome();}}
function studentHome(){const cs=enrolls().map(e=>get(e.course_id)).filter(Boolean),current=cs[0];const due=own('submissions').filter(s=>s.status==='pending').length,attempts=own('attempts'),avg=attempts.length?Math.round(attempts.reduce((x,a)=>x+a.score,0)/attempts.length):0;const ls=current?lessons(current.id):[],next=ls.find(l=>!completed(l.id))||ls[0],last=get(S.lastLesson)||next;const events=K('event').filter(e=>Date.parse(e.data.start)>Date.now()).sort((a,b)=>a.data.start.localeCompare(b.data.start)).slice(0,3);
 return `<div class="welcome"><h1>Hoş geldin, ${esc(S.user.name.split(' ')[0])}! 👋</h1><p>${esc(JSON.parse(S.settings||'{}').welcome||'Bugün de İngilizcene bir adım daha yaklaşalım.')}</p><img src="/assets/welcome-alpaka.png" alt="Apaka"><blockquote>“Small progress<br>is still progress!” ♡</blockquote></div>${current?`<div class="card program"><div class="row">${badge('pen')}<div class="grow"><h3>${esc(current.title)}</h3><p>İlerleme Durumun</p></div>${B('nav','lesson/'+next?.id,'Programa Devam Et →','btn soft')}</div><div class="row"><div class="grow">${progress(percent(current.id))}</div><small class="muted">${ls.filter(l=>completed(l.id)).length} / ${ls.length} ders tamamlandı</small></div></div>`:`<div class="card">${E('book','Henüz bir programa kayıtlı değilsin. İngilizce yolculuğuna başlayalım.','courses','Eğitimleri Keşfet →')}</div>`}<div class="grid six" style="margin-bottom:23px">${[['lessons','book','Derslerim',cs.reduce((a,c)=>a+lessons(c.id).length,0)+' Ders',''],['homework','pen','Ödevlerim',due+' Değerlendirme Bekliyor',''],['quizzes','quiz','Quizler',avg+'% Ortalama','purple'],['speaking','chat','Speaking Club','Katılım Sağla','pink'],['resources','file','Kaynaklar','PDF & Ekstra',''],['certificates','trophy','Sertifikalarım',own('certificates').length+' Tamamlanan','gold']].map(([n,i,l,s,c])=>B('nav',n,badge(i,c)+'<strong>'+l+'</strong><small>'+s+'</small>','tile')).join('')}</div><div class="grid two"><div class="card"><div class="row between"><h2>Son İzlediğin Ders</h2>${B('nav','lessons','Tümünü Gör','link')}</div>${last?`<div class="row"><img class="thumbnail" src="/assets/lesson-poster.jpg" alt="Ders önizlemesi"><div><h3>${esc(last.title)}</h3><p class="muted">${esc(last.data.module)}</p>${B('nav','lesson/'+last.id,'Devam Et →','btn small')}</div></div>`:E('play','Dersin burada görünecek.')}</div><div class="card"><div class="row between"><h2>Yaklaşan Etkinlikler</h2>${B('nav','calendar','Tümünü Gör','link')}</div>${events.map(eventRow).join('')||E('calendar','Yaklaşan etkinlik yok.')}</div></div><div class="grid two"><div class="card"><h2>Son Aktivitelerim</h2>${own('attempts').slice(-2).reverse().map(a=>`<div class="listrow">${badge('quiz','purple')}<div><b>${esc(get(a.quiz_id)?.title||'Quiz')} · ${a.score}%</b><p class="muted">${date(a.created)}</p></div></div>`).join('')||E('chart','Ders ve quiz sonuçların burada görünecek.')}</div><div class="card"><h2>İngilizce yolculuğun</h2><p class="muted">Seviyene uygun programı keşfet; derslerini, ödevlerini ve gelişimini tek panelden takip et.</p><div class="inline-actions">${B('nav','courses','Eğitimleri Keşfet','btn soft')}${B('nav','placement','Seviyeni Öğren','btn outline')}</div></div></div>`;
}
function eventRow(e){return `<div class="listrow">${badge(e.data.type==='Speaking Club'?'chat':'calendar',e.data.type==='Speaking Club'?'purple':'blue')}<div class="grow"><b>${esc(e.title)}</b><p class="muted">${datetime(e.data.start)}</p></div>${B('event-detail',e.id,'Detay','btn small soft')}</div>`;}
function courses(admin){const cs=K('course').filter(c=>admin||c.data.published).filter(c=>catalogFilter==='all'||catalogFilter==='seasonal'&&c.data.seasonal||c.data.level===catalogFilter);return pageHead(admin?'Eğitimler':'Eğitimleri Keşfet','A1’den C1’e, seviyene uygun İngilizce programları.',admin?B('edit-course','','+ Yeni Eğitim'):B('nav','placement','Seviyeni Öğren','btn soft'))+`<div class="tabs">${['all','A1','A2','B1','B2','C1','seasonal'].map(f=>B('catalog-filter',f,f==='all'?'Tümü':f==='seasonal'?'Dönemsel Programlar':f,'tab '+(catalogFilter===f?'active':''))).join('')}</div><div class="grid three">${cs.map(c=>`<article class="course card"><div class="course-banner"><b>${esc(c.data.level)}</b><img src="/assets/welcome-alpaka.png" alt="Apaka"></div><div class="row between"><h3>${esc(c.title)}</h3>${admin?pill(c.data.published?'Açık':'Kapalı',c.data.published?'':'inactive'):enrolled(c.id)?pill('Kayıtlısın'):''}</div><p class="muted">${esc(c.data.description)}</p><p class="muted">${c.data.price?money(c.data.price*100)+' · ':''}${lessons(c.id).length} ders · ${K('quiz').filter(q=>q.course_id===c.id).length} quiz · ${K('resource').filter(q=>q.course_id===c.id).length} kaynak</p>${admin?`<div class="inline-actions">${B('edit-course',c.id,'Düzenle','btn small soft')}${B('course-content',c.id,'İçerikleri Gör','btn small outline')}${B('delete-entity',c.id,'Sil','btn small danger')}</div>`:enrolled(c.id)?B('open-course',c.id,'Programa Devam Et →'):B('enroll',c.id,'Programa Katıl →')}</article>`).join('')||E('book','Bu filtreye uygun program yok.')}</div>`;}
function myLessons(){const cs=enrolls().map(e=>get(e.course_id)).filter(Boolean);return pageHead('Derslerim','Eğitimlerine devam et, ilerlemeni takip et.',B('nav','courses','Eğitimleri Keşfet','btn soft'))+(cs.map(c=>`<section class="card"><div class="row between"><h2>${esc(c.title)}</h2><span class="muted">${percent(c.id)}% tamamlandı</span></div>${progress(percent(c.id),false)}<div style="margin-top:15px">${lessons(c.id).map(l=>`<div class="listrow">${badge(completed(l.id)?'check':locked(l.id)?'lock':'play')}<div class="grow"><b>${esc(l.title)}</b><p class="muted">${esc(l.data.module)} · ${esc(l.data.duration||'Okuma dersi')}</p></div>${locked(l.id)?pill('Kilitli','inactive'):B('nav','lesson/'+l.id,completed(l.id)?'Tekrar İzle':'Başla →','btn small soft')}</div>`).join('')||E('book','Bu programın dersleri hazırlanıyor.')}</div></section>`).join('')||`<div class="card">${E('book','Henüz programa kayıtlı değilsin.','courses','Programları Gör')}</div>`);}
function lesson(){const l=get(detail);if(!l||l.kind!=='lesson')return pageHead('Ders bulunamadı')+E('book','Ders listesine dön.','lessons','Derslerim');const admin=staffView();if(!admin&&locked(l.id))return pageHead(l.title)+E('lock','Bu ders henüz açılmadı. Önce önceki dersleri tamamla.','lessons','Derslerime Dön');const c=get(l.course_id),ls=lessons(l.course_id),idx=ls.findIndex(x=>x.id===l.id),rs=K('resource').filter(r=>r.course_id===l.course_id),qs=K('quiz').filter(q=>q.course_id===l.course_id),as=K('assignment').filter(a=>a.course_id===l.course_id);return `<div class="lesson-layout"><aside class="lesson-menu">${B('nav',admin?'content':'lessons','‹ '+esc(c?.title||'Programa Dön'),'link')}<h3>${esc(l.data.module||'Dersler')}</h3>${ls.map((x,i)=>B('nav','lesson/'+x.id,I(!admin&&locked(x.id)?'lock':completed(x.id)?'check':'file')+'<span>'+(i+1)+'. '+esc(x.title)+'</span>','lesson-nav '+(x.id===l.id?'current':''))).join('')}${qs.map(q=>B('nav','quiz/'+q.id,I('quiz')+'<span>Quiz</span>','lesson-nav')).join('')}${as.map(a=>B('homework-detail',a.id,I('pen')+'<span>Homework</span>','lesson-nav')).join('')}</aside><div class="lesson-main"><div class="row between"><h1>${esc(l.title)}</h1><div class="inline-actions">${idx?B('nav','lesson/'+ls[idx-1].id,'←','btn outline small'):''}${idx<ls.length-1&& (admin||!locked(ls[idx+1].id))?B('nav','lesson/'+ls[idx+1].id,'→','btn outline small'):''}${admin?B('edit-lesson',l.id,'Düzenle','btn soft small'):''}</div></div>${l.data.videoUrl?`<video id="lesson-video" class="video" controls controlslist="nodownload" preload="metadata" poster="/assets/lesson-poster.jpg" src="${esc(l.data.videoUrl)}"><track kind="captions" src="/assets/sample-lesson.vtt" srclang="en" label="English" default></video><p class="action-note">${l.data.videoUrl==='/assets/sample-lesson.mp4'?'Örnek ders videosu · 24 saniye':''}</p>`:`<div class="card"><div class="row">${badge('book')}<div><h3>Okuma Dersi</h3><p class="muted">Aşağıdaki ders içeriğini incele.</p></div></div></div>`}<div class="tabs" style="margin-top:20px">${[['notes','Ders Notları (PDF)'],['quiz','Quiz'],['homework','Ödev'],['extras','Ek Kaynaklar']].map(([k,t])=>B('nav','lesson/'+l.id+'/'+k,t,'tab '+(lessonTab===k?'active':''))).join('')}</div><div class="card">${lessonTab==='quiz'?qs.map(q=>`<div class="listrow">${badge('quiz','purple')}<div class="grow"><b>${esc(q.title)}</b><p class="muted">${q.data.questions?.length||0} soru</p></div>${B('nav','quiz/'+q.id,'Quiz’e Başla','btn small')}</div>`).join('')||E('quiz','Henüz quiz eklenmedi.'):lessonTab==='homework'?as.map(a=>`<div class="listrow">${badge('pen')}<div class="grow"><b>${esc(a.title)}</b><p class="muted">${esc(a.data.due?date(a.data.due):'Teslim tarihi yok')}</p></div>${B('homework-detail',a.id,'Ödevi Aç','btn small')}</div>`).join('')||E('pen','Henüz ödev eklenmedi.'):lessonTab==='extras'?rs.map(resourceRow).join('')||E('file','Henüz kaynak eklenmedi.'):`<div class="lesson-copy">${esc(l.data.content)}</div>${rs.map(resourceRow).join('')}`}</div>${!admin?`<div class="row between no-print"><span class="muted">${completed(l.id)?'Bu dersi tamamladın ✓':'Dersi bitirdiğinde tamamlandı olarak işaretle.'}</span>${completed(l.id)?idx<ls.length-1?B('nav','lesson/'+ls[idx+1].id,'Sonraki Ders →'):B('nav','quizzes','Quizlere Geç →'):B('complete',l.id,'Dersi Tamamladım ✓')}</div>`:''}</div></div>`;}
function resourceRow(r){const link=r.data.fileKey?'/api/file/'+r.data.fileKey:r.data.link;return `<div class="listrow">${badge('file','pink')}<div class="grow"><b>${esc(r.title)}</b><p class="muted">${esc(r.data.description||r.data.type||'PDF')}</p></div>${link?`<a class="btn small" href="${esc(link)}" target="_blank" rel="noopener">İndir ↓</a>`:pill('Dosya bekleniyor','inactive')}</div>`;}
function resources(){const rs=K('resource').filter(r=>enrolled(r.course_id));return pageHead('Kaynaklar','PDFler, ders notları ve ek materyaller.')+`<div class="card">${rs.map(resourceRow).join('')||E('file','Kaynaklarını görmek için bir programa katıl.','courses','Eğitimleri Keşfet')}</div>`;}
function quizzes(admin){const qs=K('quiz').filter(q=>admin||enrolled(q.course_id));return pageHead(admin?'Quizler':'Quizlerim','Bilgini pekiştir, sonuçlarını takip et.',admin?B('edit-quiz','','+ Yeni Quiz'):'')+`<div class="grid two">${qs.map(q=>{const attempts=(admin?S.attempts:own('attempts')).filter(a=>a.quiz_id===q.id),best=attempts.length?Math.max(...attempts.map(a=>a.score)):null;return `<div class="card"><div class="row">${badge('quiz','purple')}<div><h3>${esc(q.title)}</h3><span class="muted">${esc(get(q.course_id)?.title)} · ${q.data.questions?.length||0} soru</span></div></div><p class="muted">Geçme puanı: ${q.data.passScore||70}%${best!==null?' · En yüksek sonuç: '+best+'%':''}</p><div class="inline-actions">${admin?B('edit-quiz',q.id,'Düzenle','btn soft')+B('quiz-results',q.id,'Sonuçlar','btn outline')+B('delete-entity',q.id,'Sil','btn danger'):B('nav','quiz/'+q.id,'Quiz’e Başla →')}${!admin&&attempts.length?B('quiz-history',q.id,'Geçmiş Sonuçlar','btn outline'):''}</div></div>`;}).join('')||`<div class="card">${E('quiz','Quizlerin burada görünecek.')}</div>`}</div>`;}
function quiz(){const q=get(detail);if(!q||q.kind!=='quiz')return E('quiz','Quiz bulunamadı.','quizzes','Quizler');return pageHead(q.title,esc(get(q.course_id)?.title||''),B('nav','quizzes','← Quizler','btn outline'))+`<div class="card"><form class="form" id="quiz-form" data-id="${esc(q.id)}">${(q.data.questions||[]).map((x,i)=>`<div class="quiz-q"><h3>${i+1}. ${esc(x.text)}</h3>${x.options.map((o,n)=>`<label class="option"><input type="radio" name="q${i}" value="${n}" required><span>${esc(o)}</span></label>`).join('')}</div>`).join('')}<p class="form-error"></p><div class="row">${B('nav','quizzes','Vazgeç','btn outline')}<button class="btn" type="submit">Quiz’i Bitir →</button></div></form></div>`;}
function homework(admin){const as=K('assignment').filter(a=>admin||enrolled(a.course_id));return pageHead(admin?'Ödevler':'Ödevlerim',admin?'Teslimleri incele, not ver ve geri bildirim gönder.':'Yazma çalışmalarını tamamla ve geri bildirimlerini gör.',admin?B('edit-assignment','','+ Yeni Ödev'):'')+`<div class="grid two">${as.map(a=>{const subs=(admin?S.submissions:own('submissions')).filter(s=>s.assignment_id===a.id),last=subs[subs.length-1];return `<div class="card"><div class="row">${badge('pen')}<div class="grow"><h3>${esc(a.title)}</h3><small class="muted">${esc(get(a.course_id)?.title)}</small></div>${last&&!admin?pill(last.status==='reviewed'?'Değerlendirildi':'Bekliyor',last.status==='reviewed'?'':'pending'):''}</div><p class="muted">${esc(a.data.instructions)}</p><p class="muted">${a.data.due?'Teslim: '+date(a.data.due):'Teslim tarihi yok'}${admin?' · '+subs.length+' teslim':''}</p>${!admin&&last?.status==='reviewed'?`<div class="notice">Not: ${last.grade}/100<br>${esc(last.feedback)}</div>`:''}<div class="inline-actions">${admin?B('edit-assignment',a.id,'Düzenle','btn soft')+B('review-list',a.id,'Teslimleri Gör','btn outline')+B('delete-entity',a.id,'Sil','btn danger'):B('homework-detail',a.id,last?'Teslimi Gör / Güncelle':'Ödevi Aç →')}</div></div>`;}).join('')||`<div class="card">${E('pen','Henüz ödev bulunmuyor.')}</div>`}</div>`;}
function speaking(){const es=K('event').filter(e=>e.data.type==='Speaking Club');return pageHead('Speaking Club','Canlı konuşma etkinliklerine katıl ve İngilizceni kullan.')+`<div class="grid two">${es.map(e=>`<div class="card"><div class="row">${badge('chat','purple')}<div><h3>${esc(e.title)}</h3><p class="muted">${datetime(e.data.start)} · ${e.data.duration||60} dakika</p></div></div><p class="muted">${esc(e.data.description)}</p>${B('event-detail',e.id,'Etkinlik Detayı →')}</div>`).join('')||E('chat','Yeni etkinlikler burada görünecek.')}</div>`;}
function calendar(admin){const dateNow=new Date(),month=new Date(dateNow.getFullYear(),dateNow.getMonth()+calendarOffset,1),first=(month.getDay()+6)%7,num=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),events=K('event').sort((a,b)=>a.data.start.localeCompare(b.data.start));let cells='';for(let i=0;i<Math.ceil((first+num)/7)*7;i++){const d=i-first+1,day=new Date(month.getFullYear(),month.getMonth(),d),ds=localDate(day);const es=events.filter(e=>localDate(new Date(e.data.start))===ds);cells+=`<div class="day ${d<1||d>num?'dim':''} ${ds===localDate(new Date())?'today':''}"><span>${day.getDate()}</span>${es.map(e=>B('event-detail',e.id,new Date(e.data.start).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'})+' '+esc(e.title),'cal-event')).join('')}</div>`;}return pageHead(admin?'Canlı Dersler & Takvim':'Takvim','Canlı dersler, Speaking Club ve yaklaşan etkinlikler.',admin?B('edit-event','','+ Yeni Etkinlik'):'')+`<div class="card"><div class="calendar-head"><h2>${month.toLocaleDateString('tr-TR',{month:'long',year:'numeric'})}</h2><div class="inline-actions">${B('month','-1','←','btn outline small')}${B('month','0','Bugün','btn soft small')}${B('month','1','→','btn outline small')}</div></div><div class="calendar">${['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].map(d=>`<div class="weekday">${d}</div>`).join('')}${cells}</div></div><div class="card"><h2>Etkinlik Listesi</h2>${events.map(eventRow).join('')||E('calendar','Henüz etkinlik yok.')}</div>`;}
function localDate(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function certificates(){return pageHead('Sertifikalarım','Programlarını tamamla, başarılarını belgele.')+`<div class="notice">Sertifika için programdaki tüm dersleri tamamlamalı ve quizlerden geçer puan almalısın. Buradaki belge Apaka program tamamlama belgesidir.</div><div class="grid two">${own('certificates').map(c=>`<div class="card"><div class="row">${badge('trophy','gold')}<div><h3>${esc(get(c.course_id)?.title)}</h3><p class="muted">Tamamlanma: ${date(c.created)}</p></div></div>${B('nav','certificate/'+encodeURIComponent(c.id),'Sertifikayı Gör →')}</div>`).join('')||`<div class="card">${E('trophy','İlk sertifikan için programını tamamla.','lessons','Derslerine Devam Et')}</div>`}</div>`;}
function certificate(){let id;try{id=decodeURIComponent(detail)}catch{id=detail}const c=own('certificates').find(c=>c.id===id);if(!c)return E('trophy','Sertifika bulunamadı.','certificates','Sertifikalarım');return pageHead('Sertifika',get(c.course_id)?.title||'',B('print','','PDF Olarak Kaydet / Yazdır','btn'))+`<section class="certificate"><img src="/assets/logo.png" alt="Apaka"><p>APAKA ENGLISH ACADEMIA</p><h1>BAŞARI SERTİFİKASI</h1><p>Bu belge</p><h2>${esc(S.user.name)}</h2><p>adlı öğrencinin <strong>${esc(get(c.course_id)?.title)}</strong><br>programındaki tüm dersleri tamamladığını ve quizlerden geçer puan aldığını belgelendirir.</p><div class="seal">☆</div><p>${date(c.created)}</p><small>Program tamamlama belgesi · ${esc(c.id)}</small></section>`;}
function profile(){return pageHead('Profil Ayarları','Kişisel bilgilerini yönet.')+`<div class="card" style="max-width:650px"><form id="profile-form" class="form"><label>Ad Soyad<input name="name" required maxlength="100" value="${esc(S.user.name)}"></label><label>E-posta<input value="${esc(S.user.email)}" disabled><small>E-posta adresin giriş hesabından alınır.</small></label><label>Seviye<input value="${esc(S.user.level)}" disabled></label><div>${B('change-password','','Şifremi Değiştir','btn outline')}</div><div class="row">${B('nav','placement','Seviyeni Öğren','btn outline')}<button class="btn">Değişiklikleri Kaydet</button></div><p class="form-error"></p></form></div>`;}
function messages(){const recipients=S.users.filter(u=>u.id!==S.user.id&&u.status!=='inactive');if(!messageRecipient||!recipients.some(u=>u.id===messageRecipient))messageRecipient=recipients[0]?.id||'';const ms=S.messages.filter(m=>(m.sender===S.user.id&&m.recipient===messageRecipient)||(m.sender===messageRecipient&&m.recipient===S.user.id));return pageHead('Mesajlar','Öğrenci ve öğretmen iletişimi.')+`<div class="card"><div class="toolbar"><h2 style="margin:0">${I('mail')} Mesajların</h2><select id="recipient" aria-label="Mesaj alıcısı">${recipients.map(u=>`<option value="${esc(u.id)}" ${u.id===messageRecipient?'selected':''}>${esc(u.name)}${u.role==='student'?'':' · '+(u.role==='teacher'?'Öğretmen':'Yönetici')}</option>`).join('')}</select></div><div class="chat">${ms.map(m=>`<div class="bubble ${m.sender===S.user.id?'mine':''}">${esc(m.body)}<small>${datetime(m.created)}</small></div>`).join('')||E('mail',messageRecipient?'Henüz mesaj yok. İlk mesajını gönder.':'Mesajlaşmak için başka bir hesap gerekli.')}</div>${messageRecipient?`<form id="message-form" class="chat-compose"><textarea name="body" required maxlength="4000" placeholder="Mesajını yaz…" aria-label="Mesaj"></textarea><button class="btn">Gönder →</button></form>`:''}</div>`;}
function payments(admin){const ps=admin?S.payments:own('payments'),pending=ps.filter(p=>p.status==='pending').reduce((x,p)=>x+p.amount,0),paid=ps.filter(p=>p.status==='paid').reduce((x,p)=>x+p.amount,0);return pageHead(admin?'Ödemeler':'Ödemelerim','Ders ve program ücretleri, vadeler ve tahsilat durumu.',admin?B('edit-payment','','+ Ödeme Ekle'):'')+`<div class="grid three">${stat('pay',money(pending),'Bekleyen Ödeme','gold')}${stat('check',money(paid),'Tahsil Edilen','')}${stat('calendar',ps.filter(p=>p.status==='pending'&&Date.parse(p.due+'T23:59:59')<Date.now()).length,'Vadesi Geçen','pink')}</div><div class="notice">Bu ekran ödeme ve tahsilat takibi içindir. Kartla ödeme veya banka tahsilatı gerçekleştirmez.</div><div class="card"><div class="toolbar"><h2 style="margin:0">Ödeme Kayıtları</h2>${B('export-payments','','CSV İndir','btn outline small')}</div><div class="tablewrap"><table class="table"><thead><tr>${admin?'<th>Öğrenci</th>':''}<th>Açıklama</th><th>Tutar</th><th>Vade</th><th>Durum</th><th>Tahsilat</th>${admin?'<th>İşlemler</th>':''}</tr></thead><tbody>${ps.map(p=>`<tr>${admin?'<td>'+esc(U(p.user_id).name)+'</td>':''}<td>${esc(p.title)}</td><td><strong>${money(p.amount)}</strong></td><td>${date(p.due)}</td><td>${pill(p.status==='paid'?'Ödendi':'Bekliyor',p.status==='paid'?'':'pending')}</td><td>${date(p.paid_at)}</td>${admin?'<td>'+B('edit-payment',p.id,'Düzenle','btn small outline')+'</td>':''}</tr>`).join('')}</tbody></table></div>${!ps.length?E('pay','Henüz ödeme kaydı yok.'):''}</div>`;}
function placement(){return pageHead('Seviyeni Öğren','Başlangıç programını seçmene yardımcı olacak kısa bir ön değerlendirme.')+`<div class="notice">Bu kısa test, resmî CEFR sınavı değildir. Sonucu program önerisi olarak kullanabilirsin.</div><div class="card"><form class="form" id="placement-form">${[['She ___ a student.',['is','are','am']],['I ___ coffee every morning.',['drinks','drink','drinking']],['Yesterday, they ___ to school.',['go','went','gone']],['She has ___ her homework.',['finish','finished','finishing']],['If I had more time, I ___ learn French.',['will','would','am']],['Despite ___ tired, she kept working.',['be','being','been']]].map(([q,os],i)=>`<div class="quiz-q"><h3>${i+1}. ${esc(q)}</h3>${os.map((v,k)=>`<label class="option"><input type="radio" name="q${i}" value="${k}" required><span>${esc(v)}</span></label>`).join('')}</div>`).join('')}<p class="form-error"></p><button class="btn">Sonucumu Gör →</button></form></div>`;}
function searchResults(raw){let q;try{q=decodeURIComponent(raw).toLocaleLowerCase('tr')}catch{q=raw.toLocaleLowerCase('tr')}const es=S.entities.filter(e=>e.title.toLocaleLowerCase('tr').includes(q)),us=staffView()?S.users.filter(u=>(u.name+' '+u.email).toLocaleLowerCase('tr').includes(q)):[];return pageHead('Arama Sonuçları','“'+q+'” için '+(es.length+us.length)+' sonuç')+`<div class="card search-results">${es.map(e=>`<div class="listrow">${badge(e.kind==='quiz'?'quiz':e.kind==='event'?'calendar':'book')}<div class="grow"><b>${esc(e.title)}</b><p class="muted">${esc(({course:'Eğitim',lesson:'Ders',quiz:'Quiz',resource:'Kaynak',assignment:'Ödev',event:'Etkinlik'})[e.kind])}</p></div>${B('search-open',e.id,'Aç →','btn soft small')}</div>`).join('')}${us.map(u=>`<div class="listrow">${badge('user')}<div class="grow"><b>${esc(u.name)}</b><p class="muted">${esc(u.email)}</p></div>${B('student-detail',u.id,'Detay','btn small outline')}</div>`).join('')}${!es.length&&!us.length?E('search','Sonuç bulunamadı.'):''}</div>`;}
function monthlyData(){const rows=[];for(let i=5;i>=0;i--){const d=new Date();d.setMonth(d.getMonth()-i);const key=d.toISOString().slice(0,7);rows.push({label:d.toLocaleDateString('tr-TR',{month:'short'}),registrations:S.users.filter(u=>u.created.startsWith(key)&&u.role==='student').length,revenue:S.payments.filter(p=>p.status==='paid'&&p.paid_at?.startsWith(key)).reduce((a,p)=>a+p.amount,0)/100});}return rows;}
function chart(type='registrations'){const ds=monthlyData(),max=Math.max(...ds.map(d=>d[type]),1),w=580,h=205,p=30;const pts=ds.map((d,i)=>[p+i*(w-2*p)/(ds.length-1),h-p-d[type]/max*(h-2*p)]);return `<svg class="chart" viewBox="0 0 ${w} ${h+25}" role="img" aria-label="Son altı ay ${type==='revenue'?'gelir':'kayıt'} grafiği"><defs><linearGradient id="fill-${type}" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#61bd96" stop-opacity=".3"/><stop offset="1" stop-color="#61bd96" stop-opacity="0"/></linearGradient></defs>${[0,.25,.5,.75,1].map(v=>`<line x1="${p}" x2="${w-p}" y1="${h-p-v*(h-2*p)}" y2="${h-p-v*(h-2*p)}" stroke="#eef2ef"/><text x="1" y="${h-p-v*(h-2*p)+4}" font-size="10" fill="#879389">${Math.round(max*v)}</text>`).join('')}${type==='revenue'?pts.map(([x,y],i)=>`<rect x="${x-18}" y="${y}" width="36" height="${h-p-y}" fill="#a0cfba" rx="3"><title>${ds[i].label}: ${money(ds[i].revenue*100)}</title></rect>`).join(''):`<path d="M${p},${h-p} ${pts.map(([x,y])=>`L${x},${y}`).join(' ')} L${w-p},${h-p}Z" fill="url(#fill-${type})"/><path d="M${pts.map(([x,y])=>`${x},${y}`).join(' L')}" stroke="#429e7c" fill="none" stroke-width="2"/>${pts.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#429e7c"><title>${ds[i].label}: ${ds[i].registrations} kayıt</title></circle>`).join('')}`}${pts.map(([x,y],i)=>`<text x="${x}" y="${h+5}" text-anchor="middle" font-size="11" fill="#89988e">${esc(ds[i].label)}</text>`).join('')}</svg>`;}
function adminHome(){const students=S.users.filter(u=>u.role==='student'),pending=S.payments.filter(p=>p.status==='pending'),revenue=S.payments.filter(p=>p.status==='paid'&&p.paid_at?.startsWith(monthFilter)).reduce((a,p)=>a+p.amount,0),subs=S.submissions.filter(s=>s.status==='pending');return pageHead('Yönetim Paneli',S.user.name+', Apaka English Academia’ya hoş geldin!',`<input type="month" id="report-month" value="${esc(monthFilter)}" aria-label="Rapor ayı" style="padding:9px;border:1px solid #e2e8e3;border-radius:8px">`)+`<div class="grid five">${stat('users',students.filter(u=>u.status==='active').length,'Aktif Öğrenci')}${stat('plus',students.filter(u=>u.created.startsWith(monthFilter)).length,'Yeni Kayıt')}${stat('pay',pending.length,'Bekleyen Ödeme','gold')}${stat('file',subs.length,'Bekleyen Ödev','pink')}${stat('chart',money(revenue),'Bu Ayki Gelir')}</div><div class="grid two"><div class="card"><h2>Aylık Kayıt Grafiği</h2>${chart()}</div><div class="card"><h2>En Çok Tercih Edilen Eğitimler</h2>${K('course').map(c=>({c,count:S.enrollments.filter(e=>e.course_id===c.id).length})).sort((a,b)=>b.count-a.count).slice(0,6).map(({c,count})=>`<div class="bar-row"><span>${esc(c.data.level)} English</span>${progress(S.enrollments.length?Math.round(count/S.enrollments.length*100):0,false)}<span>${count}</span></div>`).join('')}</div></div><div class="grid three"><div class="card"><div class="row between"><h2>Son Kayıt Olan Öğrenciler</h2>${B('nav','students','Tümünü Gör','link')}</div>${students.slice(0,4).map(u=>`<div class="listrow"><span class="avatar">${esc(u.name.charAt(0))}</span><div class="grow"><b>${esc(u.name)}</b><p class="muted">${esc(u.level)} English</p></div>${B('student-detail',u.id,date(u.created),'link')}</div>`).join('')||E('users','Henüz öğrenci yok.','students','Öğrenci Ekle')}</div><div class="card"><div class="row between"><h2>Bekleyen Ödemeler</h2>${B('nav','payments','Tümünü Gör','link')}</div>${pending.slice(0,4).map(p=>`<div class="listrow">${badge('pay','pink')}<div class="grow"><b>${esc(U(p.user_id).name)}</b><p class="muted">${esc(p.title)}</p></div><div><b>${money(p.amount)}</b><p class="muted">${date(p.due)}</p></div></div>`).join('')||E('pay','Bekleyen ödeme yok.')}</div><div class="card"><div class="row between"><h2>Bekleyen Ödevler</h2>${B('nav','homework','Tümünü Gör','link')}</div>${subs.slice(0,4).map(s=>`<div class="listrow"><span class="avatar">${esc(U(s.user_id).name.charAt(0))}</span><div class="grow"><b>${esc(U(s.user_id).name)}</b><p class="muted">${esc(get(s.assignment_id)?.title)}</p></div>${B('review',s.id,'İncele','link')}</div>`).join('')||E('pen','Değerlendirme bekleyen ödev yok.')}</div></div><div class="grid two"><div class="card"><h2>Aylık Gelir</h2>${chart('revenue')}</div><div class="card"><h2>Yaklaşan Canlı Dersler</h2>${K('event').filter(e=>Date.parse(e.data.start)>Date.now()).slice(0,4).map(eventRow).join('')||E('calendar','Yaklaşan ders yok.')}</div></div>`;}
function students(){let us=S.users.filter(u=>u.role==='student'||u.role==='teacher');const counts={all:us.length,active:us.filter(u=>u.status==='active').length,pending:us.filter(u=>S.payments.some(p=>p.user_id===u.id&&p.status==='pending')).length,inactive:us.filter(u=>u.status==='inactive').length};us=us.filter(u=>studentFilter==='all'||studentFilter==='pending'?studentFilter==='all'||S.payments.some(p=>p.user_id===u.id&&p.status==='pending'):u.status===studentFilter).filter(u=>(u.name+' '+u.email).toLocaleLowerCase('tr').includes(studentSearch.toLocaleLowerCase('tr')));return pageHead('Öğrenciler','Tüm öğrencileri görüntüle, ilerlemelerini takip et ve yönet.',B('edit-student','','+ Yeni Öğrenci Ekle'))+`<div class="card"><div class="toolbar"><div class="tabs" style="margin:0">${[['all','Tümü'],['active','Aktif'],['pending','Bekleyen Ödeme'],['inactive','Pasif']].map(([k,l])=>B('student-filter',k,l+' ('+counts[k]+')','tab '+(studentFilter===k?'active':''))).join('')}</div><div class="inline-actions"><input id="student-search" placeholder="Öğrenci ara…" aria-label="Öğrenci ara" value="${esc(studentSearch)}">${B('export-students','','CSV İndir','btn outline small')}</div></div><div class="tablewrap"><table class="table"><thead><tr><th><input type="checkbox" id="select-all" aria-label="Tüm görünen öğrencileri seç"></th><th>Öğrenci</th><th>Program</th><th>İlerleme</th><th>Ödeme Durumu</th><th>Durum</th><th>İşlemler</th></tr></thead><tbody>${us.map(u=>{const es=S.enrollments.filter(e=>e.user_id===u.id),pending=S.payments.some(p=>p.user_id===u.id&&p.status==='pending');return `<tr><td><input type="checkbox" class="student-check" data-id="${esc(u.id)}" ${selected.has(u.id)?'checked':''} aria-label="${esc(u.name)} seç"></td><td><div class="row"><span class="avatar">${esc(u.name.charAt(0))}</span><div><b>${esc(u.name)}</b><small class="muted" style="display:block">${esc(u.email)}</small></div></div></td><td>${es.map(e=>esc(get(e.course_id)?.data.level||'Program')).join(', ')||'—'}</td><td>${progress(userProgress(u.id))}</td><td>${pill(pending?'Bekliyor':'Borç Yok',pending?'pending':'')}</td><td>${pill(u.status==='active'?'Aktif':'Pasif',u.status==='active'?'':'inactive')}</td><td><div class="inline-actions">${B('student-detail',u.id,'Detay','btn small outline')}${B('edit-student',u.id,'⋮','btn small soft')}</div></td></tr>`;}).join('')}</tbody></table></div>${!us.length?E('users','Bu filtreye uygun öğrenci yok.'):''}<p class="action-note">${selected.size?'Seçili: '+selected.size+' · CSV indirme seçili öğrencileri içerir.':''}</p></div>`;}
function adminContent(){const cs=K('course'),items=S.entities.filter(e=>['lesson','resource','assignment'].includes(e.kind)&&(courseFilter==='all'||e.course_id===courseFilter));return pageHead('Dersler & İçerikler','Modüller, ders videoları, PDFler ve ödev içerikleri.',`<div class="inline-actions">${B('edit-lesson','','+ Ders Ekle')}${B('edit-resource','','+ Kaynak Ekle','btn soft')}</div>`)+`<div class="toolbar"><select id="content-course" aria-label="Program filtresi"><option value="all">Tüm Programlar</option>${cs.map(c=>`<option value="${esc(c.id)}" ${c.id===courseFilter?'selected':''}>${esc(c.title)}</option>`).join('')}</select></div><div class="card"><div class="tablewrap"><table class="table"><thead><tr><th>İçerik</th><th>Program / Modül</th><th>Tür</th><th>Sıra</th><th>İşlemler</th></tr></thead><tbody>${items.map(e=>`<tr><td><strong>${esc(e.title)}</strong></td><td>${esc(get(e.course_id)?.title)}<br><small class="muted">${esc(e.data.module||'')}</small></td><td>${pill(({lesson:'Ders',resource:'Kaynak',assignment:'Ödev'})[e.kind])}</td><td>${e.data.order||'—'}</td><td><div class="inline-actions">${e.kind==='lesson'?B('nav','lesson/'+e.id,'Önizle','btn small outline'):''}${B('edit-'+e.kind,e.id,'Düzenle','btn small soft')}${B('delete-entity',e.id,'Sil','btn small danger')}</div></td></tr>`).join('')}</tbody></table></div>${!items.length?E('file','Henüz içerik bulunmuyor.'):''}</div>`;}
function reports(){const students=S.users.filter(u=>u.role==='student'),total=S.payments.filter(p=>p.status==='paid').reduce((a,p)=>a+p.amount,0),avg=S.attempts.length?Math.round(S.attempts.reduce((a,x)=>a+x.score,0)/S.attempts.length):0;return pageHead('Raporlar','Kayıt, gelir, eğitim ilerlemesi ve quiz performansı.',B('export-report','','Raporu CSV İndir','btn outline'))+`<div class="grid four">${stat('users',students.length,'Toplam Öğrenci')}${stat('chart',money(total),'Toplam Tahsilat')}${stat('quiz',avg+'%','Quiz Ortalaması','purple')}${stat('trophy',S.certificates.length,'Verilen Sertifika','gold')}</div><div class="grid two"><div class="card"><h2>Aylık Gelir</h2>${chart('revenue')}</div><div class="card"><h2>Aylık Yeni Kayıt</h2>${chart()}</div></div><div class="card"><h2>Öğrenci İlerleme ve Başarı Raporu</h2><div class="tablewrap"><table class="table"><thead><tr><th>Öğrenci</th><th>İlerleme</th><th>Quiz Ortalaması</th><th>Ödev</th><th>Sertifika</th></tr></thead><tbody>${students.map(u=>{const qs=S.attempts.filter(a=>a.user_id===u.id);return `<tr><td>${esc(u.name)}</td><td>${progress(userProgress(u.id))}</td><td>${qs.length?Math.round(qs.reduce((a,q)=>a+q.score,0)/qs.length)+'%':'—'}</td><td>${S.submissions.filter(s=>s.user_id===u.id).length}</td><td>${S.certificates.filter(c=>c.user_id===u.id).length}</td></tr>`}).join('')}</tbody></table></div>${!students.length?E('chart','Raporlar gerçek kayıtlardan oluşacak.'):''}</div>`;}
function settings(){const set=JSON.parse(S.settings||'{}');return pageHead('Ayarlar','Okul bilgileri, hesap yetkileri ve işlem geçmişi.')+`<div class="grid two"><div class="card"><h2>Okul Bilgileri</h2>${S.admin?`<form class="form" id="settings-form"><label>Okul Adı<input name="schoolName" value="${esc(set.schoolName||'Apaka English Academia')}" required></label><label>İletişim E-postası<input name="contact" type="email" value="${esc(set.contact||'')}"></label><label>Karşılama Mesajı<textarea name="welcome">${esc(set.welcome||'')}</textarea></label><p class="form-error"></p><button class="btn">Kaydet</button></form>`:E('gear','Ayarları yalnızca yönetici düzenleyebilir.')}</div><div class="card"><h2>Hesap ve Rol Yönetimi</h2>${S.users.filter(u=>u.role!=='student').map(u=>`<div class="listrow"><span class="avatar">${esc(u.name.charAt(0))}</span><div class="grow"><b>${esc(u.name)}</b><p class="muted">${esc(u.email)} · ${u.role==='admin'?'Yönetici':'Öğretmen'}</p></div>${S.admin?B('edit-student',u.id,'Düzenle','btn small outline'):''}</div>`).join('')}<p class="muted">Yeni hesaplar girişte öğrenci rolü alır. Öğretmen ve yönetici rollerini site yöneticisi atar.</p>${S.admin?B('edit-student','','+ Hesap Ekle','btn soft'):''}</div></div>${S.admin?`<div class="card"><h2>İşlem Geçmişi</h2><div class="scrollbox">${S.audit.map(a=>`<div class="listrow">${badge('file')}<div class="grow"><b>${esc(a.action)}</b><p class="muted">${esc(U(a.actor).name)} · ${datetime(a.created)}</p></div></div>`).join('')||E('file','Henüz işlem kaydı yok.')}</div></div>`:''}`;}
function courseOptions(value='',optional=false){return `${optional?'<option value="">Tüm Öğrenciler / Program Yok</option>':''}${K('course').map(c=>`<option value="${esc(c.id)}" ${c.id===value?'selected':''}>${esc(c.title)}</option>`).join('')}`;}
const input=(label,name,value='',type='text',required=true)=>`<label>${label}<input type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''}></label>`;
const textarea=(label,name,value='')=>`<label>${label}<textarea name="${name}">${esc(value)}</textarea></label>`;
function editEntity(kind,id){const e=id?get(id):null,d=e?.data||{};let fields=input('Başlık','title',e?.title||'');if(kind!=='course')fields+=`<label>Program<select name="course_id" ${kind==='event'?'':'required'}>${courseOptions(e?.course_id||(courseFilter!=='all'?courseFilter:''),kind==='event')}</select></label>`;
 if(kind==='course')fields+=`<label>Seviye<select name="level">${['A1','A2','B1','B2','C1','A1–B1'].map(v=>`<option ${d.level===v?'selected':''}>${v}</option>`).join('')}</select></label>`+textarea('Açıklama','description',d.description)+input('Program Ücreti (TL)','price',d.price||0,'number',false)+`<label class="check"><input type="checkbox" name="published" ${d.published||!e?'checked':''}>Kayda Açık</label><label class="check"><input type="checkbox" name="seasonal" ${d.seasonal?'checked':''}>Dönemsel Program</label>`;
 if(kind==='lesson')fields+=`<div class="grid two">${input('Modül','module',d.module||'Module 1')}${input('Ders Sırası','order',d.order||1,'number')}</div>`+input('Video Bağlantısı (HTTPS veya mevcut örnek video)','videoUrl',d.videoUrl||'','text',false)+`<small>Doğrudan MP4 bağlantısı kullan. Video bulunmuyorsa ders metniyle çalışır.</small>`+input('Süre','duration',d.duration||'','text',false)+textarea('Ders İçeriği','content',d.content);
 if(kind==='assignment')fields+=textarea('Ödev Açıklaması','instructions',d.instructions)+input('Teslim Tarihi','due',d.due?d.due.slice(0,10):'','date',false);
 if(kind==='resource')fields+=input('Dosya Türü','type',d.type||'PDF')+textarea('Açıklama','description',d.description)+input('Dosya Bağlantısı','link',d.link||'','text',false)+`<label>Dosya Yükle<input type="file" name="upload" accept=".pdf,.docx,.txt,.png,.jpg,.mp4"><small>PDF / belge: en fazla 10 MB. Dosya yüklediğinde mevcut dosya bağlantısı yerine kullanılır.</small></label><input type="hidden" name="fileKey" value="${esc(d.fileKey||'')}">`;
 if(kind==='event'){const start=d.start?new Date(d.start):new Date();const local=new Date(start.getTime()-start.getTimezoneOffset()*60000).toISOString().slice(0,16);fields+=`<label>Etkinlik Türü<select name="type"><option ${d.type==='Canlı Ders'?'selected':''}>Canlı Ders</option><option ${d.type==='Speaking Club'?'selected':''}>Speaking Club</option><option ${d.type==='Dönemsel Program'?'selected':''}>Dönemsel Program</option></select></label>`+input('Tarih / Saat','start',local,'datetime-local')+input('Süre (Dakika)','duration',d.duration||60,'number')+input('Canlı Ders Bağlantısı (HTTPS)','meetingUrl',d.meetingUrl||'','url',false)+textarea('Açıklama','description',d.description);}
 if(kind==='quiz'){fields+=input('Geçme Puanı (%)','passScore',d.passScore||70,'number')+`<div id="question-editors">${(d.questions?.length?d.questions:[{text:'',options:['','',''],answer:0,explanation:''}]).map(questionEditor).join('')}</div>${B('add-question','','+ Soru Ekle','btn soft')}`;}
 const names={course:'Eğitim',lesson:'Ders',quiz:'Quiz',assignment:'Ödev',resource:'Kaynak',event:'Etkinlik'};modal((e?'Düzenle: ':'Yeni ')+names[kind],`<form class="form" id="entity-form" data-kind="${kind}" data-id="${esc(id||'')}">${fields}<p class="form-error"></p><div class="row">${B('close','','Vazgeç','btn outline')}<button class="btn" type="submit">Kaydet</button></div></form>`);
}
function questionEditor(q,i){return `<fieldset class="question-editor"><legend>Soru ${i+1}</legend><label>Soru<input name="qtext" required value="${esc(q.text)}"></label>${q.options.map((o,n)=>`<label>Seçenek ${n+1}<input name="qoption" required value="${esc(o)}"></label>`).join('')}<label>Doğru Seçenek<select name="qanswer">${q.options.map((_,n)=>`<option value="${n}" ${Number(q.answer)===n?'selected':''}>Seçenek ${n+1}</option>`).join('')}</select></label><label>Açıklama<textarea name="qexplanation">${esc(q.explanation||'')}</textarea></label>${B('remove-question','','Soruyu Kaldır','btn small danger')}</fieldset>`;}
function editStudent(id){const u=S.users.find(u=>u.id===id)||{},roles=S.admin?['student','teacher','admin']:['student'];modal(u.id?'Hesabı Düzenle':'Yeni Öğrenci Ekle',`<form class="form" id="student-form" data-id="${esc(id||'')}">${input('Ad Soyad','name',u.name||'')}${input('E-posta','email',u.email||'','email')}<div class="grid two"><label>Rol<select name="role">${roles.map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${({student:'Öğrenci',teacher:'Öğretmen',admin:'Yönetici'})[r]}</option>`).join('')}</select></label><label>Durum<select name="status"><option value="active" ${u.status!=='inactive'?'selected':''}>Aktif</option><option value="inactive" ${u.status==='inactive'?'selected':''}>Pasif</option></select></label></div><label>Seviye<select name="level">${['A1','A2','B1','B2','C1'].map(l=>`<option ${u.level===l?'selected':''}>${l}</option>`).join('')}</select></label><label>Programa Ekle (İsteğe Bağlı)<select name="course_id">${courseOptions('',true)}</select></label><p class="muted">Bu kayıt öğrenci profilini hazırlar. Öğrenci aynı e-postalı hesabıyla giriş yaptığında kendi kayıtlarına bağlanır. Öğrenciye Detay ekranından bir Şifre Bağlantısı oluşturarak kayıt erişimi sağlayabilirsin.</p><p class="form-error"></p><div class="row">${B('close','','Vazgeç','btn outline')}<button class="btn">Kaydet</button></div></form>`);}
function studentDetail(id){const u=S.users.find(u=>u.id===id);if(!u)return;const es=S.enrollments.filter(e=>e.user_id===id);modal(u.name,`<p class="muted">${esc(u.email)} · ${esc(u.level)} · ${u.status==='active'?'Aktif':'Pasif'}</p><h3>Programları</h3>${es.map(e=>`<div class="listrow"><div class="grow"><b>${esc(get(e.course_id)?.title)}</b>${progress(percent(e.course_id,id))}</div>${B('remove-enrollment',id+'|'+e.course_id,'Kaldır','btn small danger')}</div>`).join('')||'<p class="muted">Henüz programı yok.</p>'}<form class="form" id="enrollment-form" data-id="${esc(id)}"><label>Programa Ekle<select name="course_id">${courseOptions()}</select></label><button class="btn soft">Programa Ekle</button><p class="form-error"></p></form><h3>Ödemeler</h3>${S.payments.filter(p=>p.user_id===id).map(p=>`<div class="listrow"><div class="grow">${esc(p.title)}</div><b>${money(p.amount)}</b>${pill(p.status==='paid'?'Ödendi':'Bekliyor',p.status==='paid'?'':'pending')}</div>`).join('')||'<p class="muted">Ödeme kaydı yok.</p>'}<div class="inline-actions" style="margin-top:20px">${B('edit-student',id,'Profili Düzenle','btn outline')}${B('message-user',id,'Mesaj Gönder','btn soft')}${S.admin?B('password-link',id,'Şifre Bağlantısı','btn outline'):''}</div>`);}
function editPayment(id){const p=S.payments.find(p=>p.id===id)||{};modal(p.id?'Ödemeyi Düzenle':'Yeni Ödeme',`<form class="form" id="payment-form" data-id="${esc(id||'')}"><label>Öğrenci<select name="user_id" required>${S.users.map(u=>`<option value="${esc(u.id)}" ${u.id===p.user_id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><label>Program<select name="course_id">${courseOptions(p.course_id,true)}</select></label>${input('Açıklama','title',p.title||'')}${input('Tutar (TL)','amount',p.amount?p.amount/100:'','number')}${input('Vade','due',p.due||localDate(new Date()),'date')}<label>Durum<select name="status"><option value="pending" ${p.status!=='paid'?'selected':''}>Bekliyor</option><option value="paid" ${p.status==='paid'?'selected':''}>Ödendi</option></select></label><p class="form-error"></p><div class="row">${B('close','','Vazgeç','btn outline')}<button class="btn">Kaydet</button></div></form>`);const a=$('#payment-form [name=amount]');a.step='.01';a.min='.01';}
function homeworkDetail(id){const a=get(id);if(!a)return;const subs=own('submissions').filter(s=>s.assignment_id===id),last=subs[subs.length-1];modal(a.title,`<p class="muted">${esc(a.data.instructions)}</p>${a.data.due?'<p class="muted">Teslim: '+date(a.data.due)+'</p>':''}${last?`<div class="notice">Son teslim: ${datetime(last.created)} · ${last.status==='reviewed'?'Not: '+last.grade+'/100 · '+esc(last.feedback):'Değerlendirme bekliyor'}${last.file_key?`<br><a href="/api/file/${esc(last.file_key)}" target="_blank" rel="noopener">Teslim dosyanı indir</a>`:''}</div>`:''}<form class="form" id="homework-form" data-id="${esc(id)}">${textarea('Cevabın','answer',last?.answer||'')}<label>Dosya Ekle (İsteğe Bağlı)<input type="file" name="upload" accept=".pdf,.docx,.txt,.jpg,.png"><small>En fazla 10 MB.</small></label><p class="form-error"></p><div class="row">${B('close','','Vazgeç','btn outline')}<button class="btn">Ödevi Gönder</button></div></form>`);}
function reviewList(id){const subs=S.submissions.filter(s=>s.assignment_id===id);modal(get(id)?.title||'Ödev Teslimleri',subs.map(s=>`<div class="listrow"><div class="grow"><b>${esc(U(s.user_id).name)}</b><p class="muted">${datetime(s.created)} · ${s.status==='reviewed'?s.grade+'/100':'Bekliyor'}</p></div>${B('review',s.id,'İncele','btn soft small')}</div>`).join('')||E('pen','Henüz teslim yok.'));}
function review(id){const s=S.submissions.find(x=>x.id===id);if(!s)return;modal('Ödev Değerlendir · '+U(s.user_id).name,`<div class="notice">${esc(get(s.assignment_id)?.title)}</div><div class="lesson-copy">${esc(s.answer)}</div>${s.file_key?`<p><a href="/api/file/${esc(s.file_key)}" target="_blank" rel="noopener" class="btn outline">Dosyayı İndir</a></p>`:''}<form class="form" id="review-form" data-id="${esc(id)}">${input('Not (0–100)','grade',s.grade??'','number')}${textarea('Geri Bildirim','feedback',s.feedback)}<p class="form-error"></p><button class="btn">Değerlendirmeyi Kaydet</button></form>`);$('#review-form [name=grade]').min=0;$('#review-form [name=grade]').max=100;}
function eventDetail(id){const e=get(id);if(!e)return;const joined=own('attendance').some(a=>a.event_id===id),past=Date.parse(e.data.start)+e.data.duration*60000<Date.now();modal(e.title,`<p class="muted">${datetime(e.data.start)} · ${e.data.duration||60} dakika</p><p class="lesson-copy">${esc(e.data.description)}</p><div class="notice">${esc(e.data.type)}${e.course_id?' · '+esc(get(e.course_id)?.title):''}<br>${S.attendance.filter(a=>a.event_id===id).length} katılımcı</div><div class="inline-actions">${staffView()?B('edit-event',id,'Düzenle','btn soft')+B('delete-entity',id,'Sil','btn danger'):past?pill('Etkinlik sona erdi','inactive'):B('join-event',id,joined?'Katılımı İptal Et':'Katıl →',joined?'btn outline':'btn')}${e.data.meetingUrl?`<a class="btn" href="${esc(e.data.meetingUrl)}" target="_blank" rel="noopener">Canlı Derse Gir ↗</a>`:pill('Toplantı bağlantısı henüz eklenmedi','inactive')}${B('ics',id,'Takvimime Ekle','btn outline')}</div>`);}
function quizResults(id,all=false){const attempts=(all?S.attempts:own('attempts')).filter(a=>a.quiz_id===id).reverse();modal(get(id)?.title||'Quiz Sonuçları',attempts.map(a=>`<div class="listrow"><div class="grow"><b>${esc(all?U(a.user_id).name:'Quiz Sonucun')}</b><p class="muted">${datetime(a.created)}</p></div>${pill(a.score+'%',a.score>=70?'':'pending')}${B('attempt-detail',a.id,'Detay','btn outline small')}</div>`).join('')||E('quiz','Henüz quiz çözülmedi.'));}
function showAttempt(result,score){modal('Quiz Sonucun',`<div class="score">${score}%</div>${result.map((r,i)=>`<div class="result ${r.correct?'':'wrong'}"><b>${i+1}. ${esc(r.question)}</b><p>${r.correct?'Doğru ✓':'Yanlış · Doğru seçenek: '+(r.answer+1)}</p>${r.explanation?'<p>'+esc(r.explanation)+'</p>':''}</div>`).join('')}<div class="row between">${B('close','','Tamam','btn outline')}${B('nav','quizzes','Quizlere Dön','btn')}</div>`);}
function notify(){const unread=S.messages.filter(m=>m.recipient===S.user.id&&!m.read_at),upcoming=K('event').filter(e=>Date.parse(e.data.start)>Date.now()).slice(0,4);modal('Bildirimler',unread.map(m=>`<div class="listrow">${badge('mail')}<div class="grow"><b>${esc(U(m.sender).name)}</b><p class="muted">${esc(m.body.slice(0,100))}</p></div>${B('message-user',m.sender,'Aç','btn soft small')}</div>`).join('')+upcoming.map(eventRow).join('')||E('bell','Yeni bildirim yok.'));}
function download(name,text,type='text/csv;charset=utf-8'){const blob=new Blob([type.startsWith('text/csv')?'\uFEFF':'',text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
function csv(rows){return rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"').join(';')).join('\r\n');}
function exportData(type){if(type==='students'){const us=S.users.filter(u=>u.role==='student'&&(!selected.size||selected.has(u.id)));download('apaka-ogrenciler.csv',csv([['Ad Soyad','E-posta','Seviye','Durum','İlerleme (%)'],...us.map(u=>[u.name,u.email,u.level,u.status,userProgress(u.id)])]));}if(type==='payments'){download('apaka-odemeler.csv',csv([['Öğrenci','Açıklama','Tutar (TL)','Vade','Durum'],...(staffView()?S.payments:own('payments')).map(p=>[U(p.user_id).name,p.title,p.amount/100,p.due,p.status])]))}if(type==='report'){download('apaka-basari-raporu.csv',csv([['Öğrenci','E-posta','İlerleme (%)','Quiz Sayısı','Sertifika Sayısı'],...S.users.filter(u=>u.role==='student').map(u=>[u.name,u.email,userProgress(u.id),S.attempts.filter(a=>a.user_id===u.id).length,S.certificates.filter(c=>c.user_id===u.id).length])]))}}
function makeICS(id){const e=get(id),d=new Date(e.data.start),end=new Date(d.getTime()+e.data.duration*60000),stamp=v=>v.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const safe=s=>String(s||'').replace(/\\/g,'\\\\').replace(/[\r\n]+/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');download('apaka-etkinlik.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Apaka//Online Dil Okulu//TR','BEGIN:VEVENT','UID:'+e.id+'@apaka','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(d),'DTEND:'+stamp(end),'SUMMARY:'+safe(e.title),'DESCRIPTION:'+safe(e.data.description),'LOCATION:'+safe(e.data.meetingUrl),'END:VEVENT','END:VCALENDAR'].join('\r\n'),'text/calendar;charset=utf-8');}
async function clicked(act,id,node){
 if(act.startsWith('edit-')&&['course','lesson','quiz','assignment','resource','event'].includes(act.slice(5)))return editEntity(act.slice(5),id);
 switch(act){case'nav':return nav(id);case'change-password':return modal('Şifremi Değiştir',`<form class="form" id="password-form">${input('Mevcut Şifre','current','','password')}${input('Yeni Şifre','password','','password')}${input('Yeni Şifre (Tekrar)','confirm','','password')}<small>En az 10 karakter, bir harf ve bir rakam.</small><p class="form-error"></p><button class="btn">Şifreyi Güncelle</button></form>`);case'password-link':{const r=await api('auth/invite',{user_id:id});modal('Şifre Belirleme Bağlantısı',`<p class="muted">Bu bağlantı 24 saat geçerli ve tek kullanımlıktır. Yalnızca ilgili öğrenciyle paylaş.</p><input readonly style="width:100%;padding:12px" value="${esc(location.origin+r.url)}" aria-label="Şifre belirleme bağlantısı"><p>${B('copy-link',location.origin+r.url,'Bağlantıyı Kopyala','btn')}</p>`);return;}case'copy-link':await navigator.clipboard.writeText(id);toast('Bağlantı kopyalandı.');return;case'close':return $('#modal').close();case'mobile-menu':return $('.shell').classList.toggle('menu-open');case'switch-view':view=staffView()?'student':'admin';localStorage.setItem('apaka-view',view);return nav('home');case'notifications':return notify();case'catalog-filter':catalogFilter=id;return render();case'student-filter':studentFilter=id;return render();case'course-content':courseFilter=id;return nav('content');case'open-course':{const ls=lessons(id),n=ls.find(x=>!completed(x.id))||ls[0];return n?nav('lesson/'+n.id):nav('lessons');}case'enroll':if(Number(get(id)?.data.price)>0){modal('Programa Katıl',`<p>${esc(get(id).title)}</p><div class="notice">Program ücreti: ${money(get(id).data.price*100)}. Programa katıldığında bu tutar ödeme takibine eklenir.</div><div class="row between">${B('close','','Vazgeç','btn outline')}${B('confirm-enroll',id,'Programa Katıl')}</div>`);return;}case'confirm-enroll':await api('course/'+id+'/enroll',{});await refresh();toast('Programa kaydın oluşturuldu.');return clicked('open-course',id);case'complete':await api('lesson/'+id+'/complete',{});await refresh();toast('Ders tamamlandı. Sonraki ders açıldı.');return;case'edit-student':return editStudent(id);case'student-detail':return studentDetail(id);case'edit-payment':return editPayment(id);case'homework-detail':return homeworkDetail(id);case'review-list':return reviewList(id);case'review':return review(id);case'event-detail':return eventDetail(id);case'quiz-results':return quizResults(id,true);case'quiz-history':return quizResults(id,false);case'attempt-detail':{const a=S.attempts.find(a=>a.id===id);return a&&showAttempt(JSON.parse(a.data),a.score);}case'month':calendarOffset=id==='0'?0:calendarOffset+Number(id);return render();case'join-event':await api('event/'+id+'/join',{cancel:own('attendance').some(a=>a.event_id===id)});await refresh();return eventDetail(id);case'ics':return makeICS(id);case'print':return window.print();case'export-students':return exportData('students');case'export-payments':return exportData('payments');case'export-report':return exportData('report');case'message-user':messageRecipient=id;return nav('messages');case'add-question':{const div=$('#question-editors');div.insertAdjacentHTML('beforeend',questionEditor({text:'',options:['','',''],answer:0,explanation:''},div.children.length));return;}case'remove-question':node.closest('fieldset').remove();return;case'delete-entity':{const e=get(id);modal('İçeriği Sil',`<p>“${esc(e?.title)}” içeriği silinecek.</p><div class="row between">${B('close','','Vazgeç','btn outline')}${B('confirm-delete',id,'Sil','btn danger')}</div>`);return;}case'confirm-delete':await api('admin/delete-entity',{id});$('#modal').close();await refresh();toast('İçerik silindi.');return;case'remove-enrollment':{const [user_id,course_id]=id.split('|');await api('admin/enrollment',{user_id,course_id,remove:true});await refresh();return studentDetail(user_id);}case'search-open':{const e=get(id);if(!e)return;switch(e.kind){case'course':catalogFilter=e.data.level;return nav('courses');case'lesson':return nav('lesson/'+e.id);case'quiz':return nav('quiz/'+e.id);case'event':return eventDetail(e.id);case'assignment':return staffView()?reviewList(e.id):homeworkDetail(e.id);case'resource':return modal(e.title,resourceRow(e));}return;}}
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(!b)return;e.preventDefault();if(b.disabled)return;const old=b.disabled;b.disabled=true;Promise.resolve(clicked(b.dataset.do,b.dataset.id,b)).catch(err=>toast(err.message,true)).finally(()=>{b.disabled=old});});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
document.addEventListener('change',e=>{if(e.target.id==='recipient'){messageRecipient=e.target.value;render()}if(e.target.id==='content-course'){courseFilter=e.target.value;render()}if(e.target.id==='report-month'){monthFilter=e.target.value;render()}if(e.target.classList.contains('student-check')){e.target.checked?selected.add(e.target.dataset.id):selected.delete(e.target.dataset.id)}if(e.target.id==='select-all'){$$('.student-check').forEach(c=>{c.checked=e.target.checked;c.checked?selected.add(c.dataset.id):selected.delete(c.dataset.id)})}});
const $$=s=>[...document.querySelectorAll(s)];
let searchTimer;
document.addEventListener('input',e=>{if(e.target.id==='student-search'){const pos=e.target.selectionStart;studentSearch=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const i=$('#student-search');i?.focus();i?.setSelectionRange(pos,pos)},200)}});
document.addEventListener('keydown',e=>{if(e.target.id==='search'&&e.key==='Enter'&&e.target.value.trim())nav('search/'+encodeURIComponent(e.target.value.trim()));});
async function upload(file,kind,id=''){const r=await fetch('/api/upload?kind='+kind+'&id='+encodeURIComponent(id),{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream'},body:file});const data=await r.json();if(!r.ok)throw Error(data.error);return data.key;}
document.addEventListener('submit',async e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const fd=new FormData(f),values=Object.fromEntries(fd),submit=f.querySelector('[type=submit]')||f.querySelector('button:not([type=button])'),error=f.querySelector('.form-error');if(error)error.textContent='';if(submit)submit.disabled=true;
 try{switch(f.id){case'password-form':await api('auth/change-password',values);$('#modal').close();toast('Şifren güncellendi. Diğer oturumlar kapatıldı.');break;case'profile-form':await api('profile',{name:values.name});await refresh();toast('Profilin güncellendi.');break;case'settings-form':await api('admin/settings',values);await refresh();toast('Ayarlar kaydedildi.');break;case'student-form':await api('admin/student',{...values,id:f.dataset.id});$('#modal').close();await refresh();toast('Hesap kaydedildi.');break;case'enrollment-form':await api('admin/enrollment',{user_id:f.dataset.id,course_id:values.course_id});await refresh();studentDetail(f.dataset.id);toast('Program kaydı eklendi.');break;case'payment-form':await api('admin/payment',{...values,id:f.dataset.id});$('#modal').close();await refresh();toast('Ödeme kaydedildi.');break;case'review-form':await api('admin/review',{...values,id:f.dataset.id});$('#modal').close();await refresh();toast('Değerlendirme kaydedildi.');break;case'message-form':await api('message',{recipient:messageRecipient,body:values.body});await refresh();toast('Mesaj gönderildi.');break;case'homework-form':{let fileKey='';const file=fd.get('upload');if(file?.size)fileKey=await upload(file,'assignment',f.dataset.id);await api('homework/'+f.dataset.id+'/submit',{answer:values.answer,fileKey});$('#modal').close();await refresh();toast('Ödevin teslim edildi.');break;}case'quiz-form':{const q=get(f.dataset.id),answers=q.data.questions.map((_,i)=>Number(fd.get('q'+i)));const r=await api('quiz/'+q.id+'/submit',{answers});await refresh();showAttempt(r.result,r.score);break;}case'placement-form':{const answers=Array.from({length:6},(_,i)=>Number(fd.get('q'+i))),r=await api('placement',{answers});await refresh();modal('Seviye Önerin',`<div class="score">${esc(r.level)}</div><p class="muted" style="text-align:center">${r.correct} / 6 doğru cevap. Bu sonuç kısa bir ön değerlendirmedir.</p><div class="row between">${B('close','','Tamam','btn outline')}${B('nav','courses','Programları Keşfet →')}</div>`);break;}case'entity-form':{const kind=f.dataset.kind;let data={...values};delete data.title;delete data.course_id;delete data.upload;if(kind==='course'){data.published=fd.has('published');data.seasonal=fd.has('seasonal')}if(kind==='event')data.start=new Date(values.start).toISOString();if(kind==='quiz')data.questions=[...f.querySelectorAll('.question-editor')].map(q=>({text:q.querySelector('[name=qtext]').value,options:[...q.querySelectorAll('[name=qoption]')].map(i=>i.value),answer:Number(q.querySelector('[name=qanswer]').value),explanation:q.querySelector('[name=qexplanation]').value}));if(kind==='resource'){const file=fd.get('upload');if(file?.size){data.fileKey=await upload(file,'resource');data.link='';}}await api('admin/entity',{id:f.dataset.id,kind,title:values.title,course_id:values.course_id||null,data});$('#modal').close();await refresh();toast('İçerik kaydedildi.');break;}}
 }catch(err){if(error)error.textContent=err.message;else toast(err.message,true)}finally{if(submit)submit.disabled=false;}});
window.addEventListener('hashchange',readRoute);
refresh().then(readRoute).catch(err=>{$('#app').innerHTML=`<div class="loading"><img src="/assets/logo.png" alt="Apaka"><p>${esc(err.message)}</p><a class="btn" href="/login.html">Giriş Yap</a><p><a href="/">Ana Sayfaya Dön</a></p></div>`});
